rule.example:

fun compute(result: Int): Int {
    val result = 42  // violation - shadows parameter 'result'
    return result
}

fun compute2(input: Int): Int {
    val result = input + 1  // no violation - different name
    return result
}


class Example {
    // violation - concrete type used for a property
    private val subscriptions: ArrayList<String> = ArrayList()

    // violation - concrete return type
    private fun sortedItems(): LinkedHashMap<String, Int> {
        return LinkedHashMap()
    }

    // preferred approach
    private val subscriptions2: MutableList<String> = mutableListOf()
    private fun sortedItems2(): Map<String, Int> {
        return linkedMapOf()
    }

    fun local() {
        val local: ArrayList<String> = ArrayList()  // no violation - local variable
    }
}
